head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gSeq;
scwin.gIsurCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF36002.xml';X < !정보--;
셋팅-- > function() {
    scwin.gSeq = $c.frame.path("../").scwin.gSeq;
} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/TrdHaltSchdl.do?method=readTrdHaltSchdl&inputMessageId=HALTSCHDLINFO_INOUT" + "&outputMessageId=HALTSCHDLINFO_INOUT" + "&SEQ=" + scwin.gSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(gSeq);
    dts_haltschdl_info.DataID = encodeURI(url);
    dts_haltschdl_info.reset();
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Update = function() {
    var vHaltschdlDd = $c.stf.getObjectValue(edt_haltschdl_dd);
    if (vHaltschdlDd > 0 && vHaltschdlDd.length < 8) {
        $c.win.alert("매매거래정지예정일을 올바르게 입력하시오.");
        edt_haltschdl_dd.focus();
        return;
    }
    var vReleasDd = $c.stf.getObjectValue(edt_releas_dd);
    if (vReleasDd > 0 && vReleasDd.length < 8) {
        $c.win.alert("매매거래해제예정일을 올바르게 입력하시오.");
        edt_releas_dd.focus();
        return;
    }
    var vNewschdlDd = $c.stf.getObjectValue(edt_newschdl_dd);
    if (vNewschdlDd > 0 && vNewschdlDd.length < 8) {
        $c.win.alert("신주권교부예정일을 올바르게 입력하시오.");
        edt_newschdl_dd.focus();
        return;
    }
    var vListschdlDd = $c.stf.getObjectValue(edt_listschdl_dd);
    if (vListschdlDd > 0 && vListschdlDd.length < 8) {
        $c.win.alert("상장예정일을 올바르게 입력하시오.");
        edt_listschdl_dd.focus();
        return;
    }
    dts_haltschdl.insertRow();
    dts_haltschdl.setCellData(1, "SEQ", scwin.gSeq);
    dts_haltschdl.setCellData(1, "HALT_SCHDL_DD", vHaltschdlDd);
    dts_haltschdl.setCellData(1, "HALT_RELEAS_SCHDL_DD", vReleasDd);
    dts_haltschdl.setCellData(1, "NEWSTK_SCHDL_DD", vNewschdlDd);
    dts_haltschdl.setCellData(1, "LIST_SCHDL_DD", vListschdlDd);
    dts_haltschdl.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));

    //alert(dts_haltschdl.text);

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_haltschdl.Action = "/TrdHaltSchdl.do?method=modifyTrdHaltSchdl&inputMessageId=HALTSCHDLINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_haltschdl.KeyName = "toinb_dataid4";
        trs_haltschdl.KeyValue = "JSP(I:pInput=dts_haltschdl)";
        trs_haltschdl.Post();
    }
};
scwin.fn_Delete = function() {
    dts_haltschdl.insertRow();
    dts_haltschdl.setCellData(1, "SEQ", scwin.gSeq);
    dts_haltschdl.setCellData(1, "EMP_NO", js_emp_no);

    //alert(dts_haltschdl.text);

    var vAnswer = confirm('삭제 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_haltschdl.Action = "/TrdHaltSchdl.do?method=removeTrdHaltSchdl&inputMessageId=HALTSCHDLINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_haltschdl.KeyName = "toinb_dataid4";
        trs_haltschdl.KeyValue = "JSP(I:pInput=dts_haltschdl)";
        trs_haltschdl.Post();
    }
};
scwin.img_haltschdl_dd_onclick = function() {
    popUpCalendar2(edt_haltschdl_dd);
};
scwin.img_releas_dd_onclick = function() {
    popUpCalendar2(edt_releas_dd);
};
scwin.img_newschdl_dd_onclick = function() {
    popUpCalendar2(edt_newschdl_dd);
};
scwin.img_listschdl_dd_onclick = function() {
    popUpCalendar2(edt_listschdl_dd);
};
scwin.img_save_onclick = function() {
    scwin.fn_Update();
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_del_onclick = function() {
    scwin.fn_Delete();
};
scwin.trs_haltschdl_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.trs_haltschdl_OnFail = function() {
    $c.win.alert('trs_haltschdl.OnFail() :' + trs_haltschdl.ErrorMsg);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    fn_GetParentValue();
    // 가우스헤더 셋팅
    dts_haltschdl.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=HALTSCHDLINFO_INOUT";
    dts_haltschdl.reset();
    dts_haltschdl_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=HALTSCHDLINFO_INOUT";
    dts_haltschdl_info.reset();
    $c.stf.showObj(txb_seq, false);
    //  정보 읽어오기
    fn_ReadInfo();
};
